<script setup>import {router,useForm} from '@inertiajs/vue3'; import AppLayout from '../../../Layouts/AppLayout.vue'; const props=defineProps({entry:Object,endpoints:Object}); const reverse=useForm({reason:''}); const post=()=>router.post(props.endpoints.post);</script>
<template><AppLayout :title="entry.number" eyebrow="Asiento contable trazable" :description="`${entry.date} · ${entry.status}`"><template #header-actions><button v-if="entry.status==='draft'" class="btn-primary" @click="post">Contabilizar</button></template><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><div class="live-metric" data-tone="blue"><p>Total debe</p><strong>C$ {{entry.total_debit}}</strong></div><div class="live-metric" data-tone="emerald"><p>Total haber</p><strong>C$ {{entry.total_credit}}</strong></div><div class="live-metric" data-tone="gold"><p>Período</p><strong class="text-lg">{{entry.accounting_period?.name||'—'}}</strong></div><div class="live-metric" data-tone="rose"><p>Documento</p><strong class="text-lg">{{entry.document_number||'Sin soporte'}}</strong></div></section><section class="card mt-4 p-5"><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><div><small class="text-slate-400">Concepto</small><p class="font-semibold">{{entry.concept}}</p></div><div><small class="text-slate-400">Contraparte</small><p class="font-semibold">{{entry.counterparty_name||'—'}}</p><p class="text-xs text-slate-500">{{entry.counterparty_ruc}}</p></div><div><small class="text-slate-400">Creado por</small><p class="font-semibold">{{entry.user?.name}}</p></div><div><small class="text-slate-400">Contabilizado por</small><p class="font-semibold">{{entry.posted_by?.name||'Pendiente'}}</p></div></div></section><section class="card mt-4 overflow-hidden"><div class="section-heading"><h2 class="font-semibold">Detalle de doble partida</h2><p class="text-xs text-slate-400">{{entry.reference}}</p></div><div class="table-wrap"><table class="w-full"><thead><tr><th class="table-cell">Cuenta</th><th class="table-cell">Centro de costo</th><th class="table-cell">Detalle</th><th class="table-cell text-right">Debe</th><th class="table-cell text-right">Haber</th></tr></thead><tbody><tr v-for="line in entry.lines" :key="line.id"><td class="table-cell">{{line.account.code}} · {{line.account.name}}</td><td class="table-cell">{{line.cost_center?`${line.cost_center.code} · ${line.cost_center.name}`:'—'}}</td><td class="table-cell">{{line.detail}}</td><td class="table-cell text-right">{{line.debit}}</td><td class="table-cell text-right">{{line.credit}}</td></tr></tbody></table></div></section><section v-if="entry.audit_events?.length" class="card mt-4 p-5"><h2 class="font-semibold">Bitácora inmutable</h2><div v-for="event in entry.audit_events" :key="event.id" class="mt-3 flex justify-between border-t pt-3 text-xs"><span><strong>{{event.action}}</strong><small class="block text-slate-400">{{event.actor?.name||'Sistema'}}</small></span><time>{{event.occurred_at}}</time></div></section><form v-if="entry.status==='posted'&&!entry.reversal" class="card mt-4 max-w-xl p-5" @submit.prevent="reverse.post(endpoints.reverse)"><h2 class="font-semibold">Registrar reversión</h2><label class="field-label mt-3 block">Motivo<textarea v-model="reverse.reason" class="control" required></textarea></label><button class="btn-danger mt-3">Reversar con asiento compensatorio</button></form></AppLayout></template>
